-- Controlled raw-material issues to production batches.
alter table public.stock_ledger drop constraint if exists stock_ledger_source_type;
alter table public.stock_ledger add constraint stock_ledger_source_type check(source_transaction_type in('GRN','PRODUCTION_ENTRY','ADJUSTMENT','OPENING_BALANCE','TRANSFER','MATERIAL_ISSUE'));
create sequence if not exists public.seq_material_issue start 1;
create table public.material_issues(material_issue_id uuid primary key default gen_random_uuid(),issue_no text not null unique,production_batch_id uuid not null references public.production_batches(production_batch_id),issue_date date not null default current_date,issued_by text not null,received_by text,remarks text,status text not null default'POSTED' check(status in('POSTED','REVERSED')),created_at timestamptz not null default now(),created_by text not null default'system');
create table public.material_issue_lines(material_issue_line_id uuid primary key default gen_random_uuid(),material_issue_id uuid not null references public.material_issues(material_issue_id)on delete cascade,line_no int not null,material_id uuid not null references public.materials(material_id),quantity numeric not null check(quantity>0),uom_id uuid not null references public.uoms(uom_id),location_id uuid not null references public.locations(location_id),ownership text not null,remarks text,ledger_entry_id uuid not null references public.stock_ledger(stock_ledger_id),created_at timestamptz not null default now(),created_by text not null default'system',unique(material_issue_id,line_no));
create or replace function public.issue_factory_materials(p_batch uuid,p_issued_by text,p_received_by text,p_remarks text,p_lines jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;v_no text;v_line jsonb;v_n int:=0;v_balance numeric;v_ledger uuid;v_material uuid;v_uom uuid;v_location uuid;v_ownership text;v_qty numeric;begin if not has_factory_role(auth.uid(),array['admin','store','production_manager','supervisor'])then raise exception'not authorized';end if;if nullif(trim(p_issued_by),'')is null then raise exception'issued by is required';end if;if jsonb_typeof(p_lines)<>'array'or jsonb_array_length(p_lines)=0 then raise exception'at least one line is required';end if;if not exists(select 1 from production_batches where production_batch_id=p_batch and status in('ASSIGNED','SETUP','RUNNING'))then raise exception'batch is not open for material issue';end if;v_no:='MI-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('seq_material_issue')::text,4,'0');insert into material_issues(issue_no,production_batch_id,issued_by,received_by,remarks,created_by)values(v_no,p_batch,p_issued_by,p_received_by,p_remarks,auth.uid()::text)returning material_issue_id into v_id;for v_line in select value from jsonb_array_elements(p_lines)loop v_n:=v_n+1;v_material:=(v_line->>'material_id')::uuid;v_uom:=(v_line->>'uom_id')::uuid;v_location:=(v_line->>'location_id')::uuid;v_ownership:=coalesce(nullif(v_line->>'ownership',''),'INTERCONVERTERS_OWNED');v_qty:=(v_line->>'quantity')::numeric;select coalesce(sum(quantity),0)into v_balance from stock_ledger where material_id=v_material and uom_id=v_uom and location_id=v_location and ownership=v_ownership and stock_category='RAW_MATERIAL';if v_qty<=0 or v_balance<v_qty then raise exception'insufficient material stock on line % (available: %)',v_n,v_balance;end if;insert into stock_ledger(material_id,quantity,uom_id,location_id,ownership,stock_category,source_transaction_type,source_transaction_id,batch_id,reference_note,created_by)values(v_material,-v_qty,v_uom,v_location,v_ownership,'RAW_MATERIAL','MATERIAL_ISSUE',v_id,p_batch,v_no,auth.uid()::text)returning stock_ledger_id into v_ledger;insert into material_issue_lines(material_issue_id,line_no,material_id,quantity,uom_id,location_id,ownership,remarks,ledger_entry_id,created_by)values(v_id,v_n,v_material,v_qty,v_uom,v_location,v_ownership,v_line->>'remarks',v_ledger,auth.uid()::text);end loop;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Materials Issued','material_issues',v_id,jsonb_build_object('issue_no',v_no,'batch_id',p_batch,'line_count',v_n));return v_id;end$$;
alter table public.material_issues enable row level security;alter table public.material_issue_lines enable row level security;create policy factory_read_material_issues on public.material_issues for select using(has_factory_role(auth.uid()));create policy factory_read_material_issue_lines on public.material_issue_lines for select using(has_factory_role(auth.uid()));grant execute on function public.issue_factory_materials(uuid,text,text,text,jsonb)to authenticated;
